l_path\":\"/ru/library/bg/6/11-12/\"},{\"display_name\":\"Slovenčina (Slovak)\",\"language_code\":\"sk\",\"enabled\":true,\"url_path\":\"/sk/library/bg/6/11-12/\"},{\"display_name\":\"Slovenščina (Slovenian)\",\"language_code\":\"sl\",\"enabled\":true,\"url_path\":\"/sl/library/bg/6/11-12/\"},{\"display_name\":\"Українська мова (Ukrainian)\",\"language_code\":\"uk\",\"enabled\":true,\"url_path\":\"/uk/library/bg/6/11-12/\"},{\"display_name\":\"isiZulu (Zulu)\",\"language_code\":\"zu\",\"enabled\":false,\"url_path\":\"/zu/\"}],\"breadcrumb\":[{\"url_path\":\"/en/library/\",\"title\":\"Library\"},{\"url_path\":\"/en/library/bg/\",\"title\":\"Bhagavad-gītā As It Is\"},{\"url_path\":\"/en/library/bg/6/\",\"title\":\"Chapter Six: Dhyāna-yoga\"}],\"url_path\":\"/en/library/bg/6/11-12/\",\"bb\":1617,\"has_advanced_view\":false,\"pager\":{\"previous\":{\"url_path\":\"/en/library/bg/6/10/\",\"title\":\"TEXT 10\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]},\"next\":{\"url_path\":\"/en/library/bg/6/13-14/\",\"title\":\"TEXTS 13-14\",\"has_advanced_view\":false,\"translations\":[\"en\",\"cs\",\"es\",\"bg\",\"pt-br\",\"ru\",\"sk\",\"hr\",\"pl\",\"da\",\"de\",\"et\",\"fr\",\"hu\",\"ko\",\"lt\",\"nl\",\"sl\",\"uk\",\"ja\"]}},\"child_items\":[{\"section\":\"devanagari\",\"section_title\":\"Books.Verse.devanagari\",\"children\":[{\"type\":\"content.DevanagariRecord\",\"title\":\"devanagari\",\"id\":1829,\"bb\":568118,\"url_path\":\"/en/library/bg/6/11-12/devanagari/\",\"body_final\":\"श‍ुचौ देशे प्रतिष्ठाप्य स्थिरमासनमात्मन: ।
नात्युच्छ्रितं नातिनीचं चैलाजिनकुशोत्तरम् ॥ ११ ॥
तत्रैकाग्रं मन: कृत्वा यतचित्तेन्द्रियक्रिय ।
उपविश्यासने युञ्‍ज्याद्योगमात्मविश‍ुद्धये ॥ १२ ॥\"}]},{\"section\":\"verse_text\",\"section_title\":\"Books.Verse.verse-text\",\"children\":[{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":1830,\"bb\":1618,\"url_path\":\"/en/library/bg/6/11-12/b1618/\",\"body_value\":\"śucau deśe pratiṣṭhāpya
sthiram āsanam ātmanaḥ
nāty-ucchritaṁ nāti-nīcaṁ
cailājina-kuśottaram\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":1831,\"bb\":1619,\"url_path\":\"/en/library/bg/6/11-12/b1619/\",\"body_value\":\"tatraikāgraṁ manaḥ kṛtvā
yata-cittendriya-kriyaḥ
upaviśyāsane yuñjyād
yogam ātma-viśuddhaye\"}]},{\"section\":\"synonyms\",\"section_title\":\"Books.Verse.synonyms\",\"children\":[{\"type\":\"books.Synonyms\",\"title\":\"synonyms\",\"id\":1832,\"bb\":1620,\"url_path\":\"/en/library/bg/6/11-12/b1620/\",\"shadow_value\":\"śucau – in a sanctified; deśe – land; pratiṣṭhāpya – placing; sthiram – firm; āsanam – seat; ātmanaḥ – his own; na – not; ati – too; ucchritam – high; na – nor; ati – too; nīcam – low; caila-ajina – of soft cloth and deerskin; kuśa – and kuśa grass; uttaram – covering; tatra – thereupon; eka-agram – with one attention; manaḥ – mind; kṛtvā – making; yata-citta – controlling the mind; indriya – senses; kriyaḥ – and activities; upaviśya – sitting; āsane – on the seat; yuñjyāt – should execute; yogam – yoga practice; ātma – the heart; viśuddhaye – for clarifying.\",\"word_for_word_value\":[{\"word\":\"śucau\",\"translation\":\"in a sanctified\"},{\"word\":\"deśe\",\"translation\":\"land\"},{\"word\":\"pratiṣṭhāpya\",\"translation\":\"placing\"},{\"word\":\"sthiram\",\"translation\":\"firm\"},{\"word\":\"āsanam\",\"translation\":\"seat\"},{\"word\":\"ātmanaḥ\",\"translation\":\"his own\"},{\"word\":\"na\",\"translation\":\"not\"},{\"word\":\"ati\",\"translation\":\"too\"},{\"word\":\"ucchritam\",\"translation\":\"high\"},{\"word\":\"na\",\"translation\":\"nor\"},{\"word\":\"ati\",\"translation\":\"too\"},{\"word\":\"nīcam\",\"translation\":\"low\"},{\"word\":\"caila-ajina\",\"translation\":\"of soft cloth and deerskin\"},{\"word\":\"kuśa\",\"translation\":\"and kuśa grass\"},{\"word\":\"uttaram\",\"translation\":\"covering\"},{\"word\":\"tatra\",\"translation\":\"thereupon\"},{\"word\":\"eka-agram\",\"translation\":\"with one attention\"},{\"word\":\"manaḥ\",\"translation\":\"mind\"},{\"word\":\"kṛtvā\",\"translation\":\"making\"},{\"word\":\"yata-citta\",\"translation\":\"controlling the mind\"},{\"word\":\"indriya\",\"translation\":\"senses\"},{\"word\":\"kriyaḥ\",\"translation\":\"and activities\"},{\"word\":\"upaviśya\",\"translation\":\"sitting\"},{\"word\":\"āsane\",\"translation\":\"on the seat\"},{\"word\":\"yuñjyāt\",\"translation\":\"should execute\"},{\"word\":\"yogam\",\"translation\":\"yoga practice\"},{\"word\":\"ātma\",\"translation\":\"the heart\"},{\"word\":\"viśuddhaye\",\"translation\":\"for clarifying\"}]}]},{\"section\":\"translation\",\"section_title\":\"Books.Verse.translation\",\"children\":[{\"type\":\"content.Record\",\"title\":\"translation\",\"id\":1833,\"bb\":1621,\"url_path\":\"/en/library/bg/6/11-12/b1621/\",\"body_value\":\"To practice yoga, one should go to a secluded place and should lay kuśa grass on the ground and then cover it with a deerskin and a soft cloth. The seat should be neither too high nor too low and should be situated in a sacred place. The yogī should then sit on it very firmly and practice yoga to purify the heart by controlling his mind, senses and activities and fixing the mind on one point.\"}]},{\"section\":\"purport\",\"section_title\":\"Books.Verse.purport\",\"children\":[{\"type\":\"content.Record\",\"title\":\"paragraph\",\"id\":1834,\"bb\":1622,\"url_path\":\"/en/library/bg/6/11-12/b1622/\",\"body_value\":\"“Sacred place” refers to places of pilgrimage. In India the yogīs – the transcendentalists or the devotees – all leave home and reside in sacred places such as Prayāga, Mathurā, Vṛndāvana, Hṛṣīkeśa and Hardwar and in solitude practice yoga where the sacred rivers like the Yamunā and the Ganges flow. But often this is not possible, especially for Westerners. The so-called yoga societies in big cities may be successful in earning material benefit, but they are not at all suitable for the actual practice of yoga. One who is not self-controlled and whose mind is not undisturbed cannot practice meditation. Therefore, in the Bṛhan-nāradīya Purāṇa it is said that in Kali-yuga (the present yuga, or age), when people in general are short-lived, slow in spiritual realization and always disturbed by various anxieties, the best means of spiritual realization is chanting the holy name of the Lord.\"},{\"type\":\"content.Record\",\"title\":\"verse_text\",\"id\":1835,\"bb\":1623,\"url_path\":\"/en/library/bg/6/11-12/b1623/\",\"body_value\":\"harer nāma harer nāma
harer nāmaiva kevalam
kalau nāsty eva nāsty eva
